// Batch-generated by scripts/compute_scan_history.py (data/scans/*_history.json,
// baked in at build time, same static-import convention as lib/scanDays.ts /
// lib/strategyData.ts, not fetched at runtime).
//
// Each scan's data lives in its own module under lib/scanHistoryData/ and is
// imported only by the page that uses it. Do NOT re-introduce a lookup table
// of all scans here: it would pull every history file into every page that
// imports it. To extend the /history view to another scan, add a module there
// and pass its data to <ScanHistoryView data={...} />. (/market-stage and
// /stage-analysis use stage-change runs instead, see lib/stageTransitions.ts.)

export interface ScanHistoryTicker {
  ticker: string;
  hitDates: string[]; // ISO dates, ascending, within the batch's window (90d)
  hitCount: number;
  closeByDate: Record<string, number>;
  firstSeen: string;
  lastSeen: string;
  firstClose: number;
  lastClose: number;
  pctChange: number | null;
  // lekkung/sepa/kell/breakout/oneil only: start of each setup (scripts/scan_setups.py),
  // may be before hitDates[0] when the setup began before the 90-day window
  setupStarts?: string[];
}

export interface ScanHistoryData {
  generatedAt: string;
  scan: string;
  windowDays: number;
  tickers: ScanHistoryTicker[];
}
